def first_unique(s: str) -> str | None:
    """Return the first character that occurs exactly once in the string.
    Case‑sensitive. Returns None if no such character exists."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in s:
        if counts[ch] == 1:
            return ch
    return None


# ----- tests -------------------------------------------------
import unittest

class TestFirstUnique(unittest.TestCase):
    def test_empty(self):
        self.assertIsNone(first_unique(""))          # no characters

    def test_aabbc(self):
        self.assertEqual(first_unique("aabbc"), "c")

    def test_swiss(self):
        # 'S' and 'w' appear once; 'S' is first
        self.assertEqual(first_unique("Swiss"), "S")

    def test_abccba(self):
        self.assertIsNone(first_unique("abccba"))    # every char repeats

if __name__ == "__main__":
    unittest.main()
